-- ---- fibers — ON CONFLICT (name) -------------------------------------
insert into fibers (name, is_fodmap_trigger, fermentability, notes) values
  ('inulin', true, 'high', 'Fructan. Top bacterial fuel AND classic IBS trigger. Chicory, jerusalem artichoke, onion, garlic.'),
  ('fos', true, 'high', 'Fructo-oligosaccharide; shorter-chain fructan, distinct from inulin. Onion, garlic, asparagus.'),
  ('gos', true, 'high', 'Galacto-oligosaccharide. Legumes and some dairy. A FODMAP trigger.'),
  ('rs2', false, 'moderate', 'Resistant starch, native granular form. Green banana, raw potato starch, legumes.'),
  ('rs3', false, 'moderate', 'Retrograded resistant starch, formed when cooked starch is cooled. Cooled rice and potato.'),
  ('pectin', false, 'moderate', 'Soluble, gentle, gel-forming. Apple, citrus, carrot. Feeds butyrate producers.'),
  ('beta_glucan', false, 'moderate', 'Soluble fiber of oats, barley and mushrooms. Feeds propionate producers; lowers cholesterol.'),
  ('arabinoxylan', false, 'moderate', 'Major fiber of whole wheat, rye and bran. Commonly overlooked; feeds Base Layer and Appetite Crew.'),
  ('psyllium', false, 'low', 'Husk fiber. Poorly fermented, so it bulks mechanically rather than feeding much.'),
  ('mucilage', false, 'moderate', 'Gel fiber of chia, flax and okra. Fermentable; soothes and feeds butyrate producers.')
on conflict (name) do update set
  is_fodmap_trigger = excluded.is_fodmap_trigger,
  fermentability = excluded.fermentability,
  notes = excluded.notes;

