-- ---- districts — update-then-insert (order is unique per world now) --
update districts d set name = v.name, unlock_rule_key = v.unlock_rule_key
from (values
  (1, 'The Backbone District', 'tier2_unlocked'),
  (2, 'The Keystones', 'two_backbone_blooming'),
  (3, 'The Scientists', 'one_keystone_blooming_and_10_days'),
  (4, 'The Hidden Gems', 'after_d3_engagement')
) as v("order", name, unlock_rule_key)
where d."order" = v."order";
insert into districts ("order", name, unlock_rule_key)
select * from (values
  (1, 'The Backbone District', 'tier2_unlocked'),
  (2, 'The Keystones', 'two_backbone_blooming'),
  (3, 'The Scientists', 'one_keystone_blooming_and_10_days'),
  (4, 'The Hidden Gems', 'after_d3_engagement')
) as v("order", name, unlock_rule_key)
where not exists (select 1 from districts d where d."order" = v."order");

-- ---- guilds — ON CONFLICT (internal_name); Fence 2 claim_risk -------
insert into guilds (district_id, internal_name, display_name, function_copy, confidence_tag, feeds_copy, claim_risk, substantiation)
select d.id, v.internal_name, v.display_name, v.function_copy, v.confidence_tag::confidence_tag, v.feeds_copy, v.claim_risk, v.substantiation
from (values
  (1, 'anti_inflammatory_arsenal', 'The Anti-inflammatory Arsenal', 'Butyrate producers (Faecalibacterium, Roseburia) that fuel the gut lining and calm inflammation. The backbone.', 'solid', 'Resistant starch, pectin, beta-glucan, oats and beans', false, null),
  (1, 'appetite_crew', 'The Appetite Crew', 'Propionate producers (Bacteroides) tied to satiety, steadier blood sugar and lower cholesterol.', 'solid', 'Beta-glucan, barley, arabinoxylan and seaweed', false, null),
  (1, 'base_layer', 'The Base Layer', 'Bifidobacteria that acidify the gut, crowd out pathogens and feed everyone else. Base of the pyramid.', 'solid', 'Inulin, FOS and GOS, onion, garlic, chicory and legumes', false, null),
  (1, 'recycling_engine', 'The Recycling Engine', 'Lactate utilizers (Anaerostipes, E. hallii) that turn lactate into more butyrate and keep the system stable.', 'solid', 'Indirect, they eat what the Base Layer makes, so feed the Base Layer', false, null),
  (2, 'locksmith', 'The Locksmith', 'Ruminococcus bromii, cracks open resistant-starch particles so everyone else can feed. Without it, RS passes straight through.', 'solid', 'Resistant starch, green banana, cooled rice and potato', false, null),
  (2, 'knights_of_the_wall', 'The Knights of the Wall', 'Akkermansia muciniphila, maintains the mucus barrier and tracks with metabolic health.', 'maturing', 'Polyphenols, cranberry, pomegranate, green tea and concord grape', false, null),
  (3, 'vitamin_lab', 'The Vitamin Lab', 'Vitamin synthesizers that produce K2, folate, biotin and B12. Where your 30-plants number cashes out into a mechanism.', 'solid', 'Overall diversity, the wider your plant range, the busier this lab', false, null),
  (3, 'mood_regulators', 'The Mood Regulators', 'Tryptophan and indole producers on the gut-brain axis; ties to the mood dashboard.', 'frontier', 'Tryptophan-rich foods (oats, seeds, soy) plus fiber', true, '[emerging science] RD-REVIEW-REQUIRED: gut-brain axis is a real and active research field, but a direct food→mood causal claim is unproven in humans. Frame as association only; never imply the app treats mood. Pending RD sign-off.'),
  (4, 'estrogen_regulators', 'The Estrogen Regulators', 'Equol producers from soy isoflavones; roughly 1 in 3 people host them. Equol is a potent phytoestrogen of cardiovascular, bone and menopause interest.', 'emerging', 'Soy isoflavones, soybean, tempeh, tofu and miso', true, '[emerging science] RD-REVIEW-REQUIRED: equol-producer status is a real metabotype confirmed only by a urine test after a soy challenge, not by tracking intake. Phytoestrogen health effects are emerging, not established. No therapeutic claim. Pending RD sign-off.'),
  (4, 'mitochondria_boosters', 'The Mitochondria Boosters', 'Urolithin producers from ellagitannins; metabotypes A/B/0. Urolithin A is studied for mitochondrial and muscle health.', 'emerging', 'Pomegranate, walnuts and berries', true, '[emerging science] RD-REVIEW-REQUIRED: urolithin-A benefits rest on early human trials and supplement studies, not whole-food outcomes. Producer status is a metabotype, not guaranteed by intake. No therapeutic claim. Pending RD sign-off.'),
  (4, 'tumor_preventors', 'The Tumor Preventors', 'Enterolignan producers from plant lignans; enterolactone is of hormonal and cardiovascular interest.', 'associational', 'Flax, sesame and rye', true, '[emerging science] RD-REVIEW-REQUIRED: ASSOCIATIONAL ONLY, NOT proven cancer prevention. Cancer-prevention claims are heavily scrutinized by FDA/FTC and app-store review. Name is placeholder; likely must be softened before launch. Pending RD sign-off.'),
  (4, 'stone_breakers', 'The Stone Breakers', 'Oxalate degraders (Oxalobacter), niche, but a clean food→function link that matters mainly for kidney-stone formers.', 'solid', 'Niche, they process oxalate from foods like spinach, beet and almond', false, null)
) as v(district_order, internal_name, display_name, function_copy, confidence_tag, feeds_copy, claim_risk, substantiation)
join districts d on d."order" = v.district_order
on conflict (internal_name) do update set
  district_id = excluded.district_id,
  display_name = excluded.display_name,
  function_copy = excluded.function_copy,
  confidence_tag = excluded.confidence_tag,
  feeds_copy = excluded.feeds_copy,
  claim_risk = excluded.claim_risk,
  substantiation = excluded.substantiation;

-- ---- plants — ON CONFLICT (name); description = field-guide blurb ----
insert into plants (name, scientific_name, plant_family, rarity_tier, description) values
  ('Garlic', 'Allium sativum', 'Amaryllidaceae', 'common', 'Tiny clove, huge inulin payload — one of the best-fed guilds'' favorite fuels, plus allicin when crushed.'),
  ('Onion', 'Allium cepa', 'Amaryllidaceae', 'common', 'The everyday prebiotic: fructans plus quercetin in the papery layers. The workhorse of gut gardens.'),
  ('Leek', 'Allium ampeloprasum', 'Amaryllidaceae', 'uncommon', 'A gentler, sweeter allium — the white base carries the fructans your microbes queue up for.'),
  ('Shallot', 'Allium cepa var. aggregatum', 'Amaryllidaceae', 'uncommon', 'Onion''s refined cousin, denser in polyphenols per bite than most of the allium family.'),
  ('Spring onion', 'Allium fistulosum', 'Amaryllidaceae', 'common', 'Two plants in one: prebiotic white bulb, chlorophyll-rich green tops. Use the whole thing.'),
  ('Chives', 'Allium schoenoprasum', 'Amaryllidaceae', 'uncommon', 'A sprinkle counts — the smallest allium still brings organosulfur compounds to the plate.'),
  ('Broccoli', 'Brassica oleracea var. italica', 'Brassicaceae', 'common', 'The famous one: sulforaphane''s parent compound lives in these florets. Steam it lightly, chew it well.'),
  ('Cauliflower', 'Brassica oleracea var. botrytis', 'Brassicaceae', 'common', 'A white-brown crucifer that roasts into sweetness — same glucosinolate family as broccoli, different fiber mix.'),
  ('Cabbage', 'Brassica oleracea var. capitata', 'Brassicaceae', 'common', 'Cheap, keeps for weeks, and ferments into kimchi and sauerkraut — the most versatile crucifer in the guide.'),
  ('Kale', 'Brassica oleracea var. sabellica', 'Brassicaceae', 'uncommon', 'Lutein and glucosinolates in a leaf sturdy enough to massage. The darker the leaf, the more it carries.'),
  ('Brussels sprouts', 'Brassica oleracea var. gemmifera', 'Brassicaceae', 'uncommon', 'Tiny cabbages with an outsized glucosinolate load. Roasting converts the skeptics.'),
  ('Bok choy', 'Brassica rapa subsp. chinensis', 'Brassicaceae', 'uncommon', 'A crucifer that cooks in minutes — crisp stems, tender greens, stir-fry''s favorite vehicle.'),
  ('Arugula', 'Eruca vesicaria', 'Brassicaceae', 'uncommon', 'The peppery bite IS the phytochemicals — erucin and friends, straight from the leaf.'),
  ('Radish', 'Raphanus sativus', 'Brassicaceae', 'common', 'A crunchy, peppery crucifer you can eat in seconds — the easy way to sneak a fourth plant into lunch.'),
  ('Turnip', 'Brassica rapa subsp. rapa', 'Brassicaceae', 'uncommon', 'Old-world staple, two foods in one: peppery root plus greens that outdo it nutritionally.'),
  ('Watercress', 'Nasturtium officinale', 'Brassicaceae', 'rare', 'Gram for gram one of the most nutrient-dense leaves known — a rare find worth hunting.'),
  ('Spinach', 'Spinacia oleracea', 'Amaranthaceae', 'common', 'Lutein, folate, and chlorophyll that wilts into anything. The gateway green.'),
  ('Romaine lettuce', 'Lactuca sativa', 'Asteraceae', 'common', 'More than crunch: water, folate, and a gentle fiber that makes salads a habit.'),
  ('Swiss chard', 'Beta vulgaris subsp. vulgaris', 'Amaranthaceae', 'rare', 'Rainbow stems, beet''s leafy cousin — betalains and magnesium in one dramatic leaf.'),
  ('Collard greens', 'Brassica oleracea var. viridis', 'Brassicaceae', 'uncommon', 'The sturdy southern crucifer — slow-cooked or raw as a wrap, fiber either way.'),
  ('Carrot', 'Daucus carota', 'Apiaceae', 'common', 'Beta-carotene''s poster child, plus pectin — a gentle fiber your butyrate-makers appreciate.'),
  ('Beet', 'Beta vulgaris', 'Amaranthaceae', 'uncommon', 'Betalains stain everything for a reason — pigment IS the payload. Roast, grate, or pickle.'),
  ('Sweet potato', 'Ipomoea batatas', 'Convolvulaceae', 'uncommon', 'Orange flesh, carotenoids, and a fiber mix that lands gently. Cool it after cooking for resistant starch.'),
  ('Potato', 'Solanum tuberosum', 'Solanaceae', 'common', 'The humble spud turns prebiotic when cooked then COOLED — potato salad is resistant-starch food.'),
  ('Parsnip', 'Pastinaca sativa', 'Apiaceae', 'rare', 'Carrot''s pale, sweeter cousin — more fiber per bite and criminally underused.'),
  ('Ginger', 'Zingiber officinale', 'Zingiberaceae', 'uncommon', 'Gingerol brings the heat; a thumb of it in a stir-fry counts as a plant all its own.'),
  ('Turmeric', 'Curcuma longa', 'Zingiberaceae', 'rare', 'Curcumin''s home. Pair with black pepper — its piperine helps curcumin along.'),
  ('Jerusalem artichoke', 'Helianthus tuberosus', 'Asteraceae', 'legendary', 'The single richest common source of inulin — a legendary feed for the deep-fiber guilds. Start small.'),
  ('Chicory root', 'Cichorium intybus', 'Asteraceae', 'legendary', 'Where supplement-bottle inulin actually comes from — the deepest prebiotic cut in the guide.'),
  ('Pumpkin', 'Cucurbita pepo', 'Cucurbitaceae', 'uncommon', 'Carotenoid-dense flesh and seeds worth roasting — two finds in one gourd.'),
